customCSS:
.t, .history { color: #565f89; }
.join { color: #9ece6a; }
.part, .quit { color: #565f89; }
.kick, .error { color: #f7768e; }
.notice { color: #e0af68; }
.action { color: #bb9af7; }
.mode, .nick, .topic, .server { color: #7dcfff; }
.highlight { color: #c0caf5; background-color: #2e3c64; border-left: 3px solid #bb9af7; padding-left: 8px; }
.reply { color: #565f89; border-left: 2px solid #7aa2f7; padding-left: 6px; }
.oper { color: #24283b; background-color: #e0af68; }
.reactions { color: #7aa2f7; background-color: #1d202f; }
.card { background-color: #1d202f; border-color: #565f89; }
.card-title { color: #7aa2f7; }
.card-desc { color: #565f89; }
.daychange { color: #565f89; border-color: #1d202f; }
